CONDITION = re.compile(r"\b(if|only if|only with|only when|unless|provided that|subject to|against)\b", re.I)
REFUSAL = re.compile(r"\b(no|not|cannot|can't|won't|refus|reject|unable)\b", re.I)
QUESTION = re.compile(r"\?\s*$|\b(which|what|when|who|how)\b", re.I)
FIELD_CUES = {"contract_months": re.compile(r"\b(contract|commitment|months?|term)s?\b", re.I),
