            expiry = datetime.datetime.fromisoformat(item["expires_at"].replace("Z", "+00:00"))
            valid_from = datetime.datetime.fromisoformat(item["valid_from"].replace("Z", "+00:00"))
        except (KeyError, TypeError, ValueError):
