class AsyncArena:
    """httpx.AsyncClient wrapper. Methods mirror arena_kit.client.ArenaClient; POSTs take a move id."""

    def __init__(
        self,
        base_url: str | None = None,
        api_key: str | None = None,
        calls_per_s: float = 8.0,
        *,
        retries: int = 3,
        transport=None,
        timeout: float = TIMEOUT_S,
        limiter: RateLimiter | None = None,
    ):
        base_url = (base_url or os.environ.get("ARENA_URL", "")).rstrip("/")
        if not base_url:
            raise ValueError("set ARENA_URL or pass base_url")
        key = api_key or os.environ.get("ARENA_API_KEY")
        headers = {"X-API-Key": key} if key else {}
        self.retries = retries
        self.limiter = limiter or RateLimiter(calls_per_s)
        self.practice_remaining: int | None = None
        self.http = httpx.AsyncClient(
            base_url=f"{base_url}/v1", headers=headers, timeout=timeout, transport=transport
        )

    async def aclose(self) -> None:
        await self.http.aclose()

    async def _call(self, method, path, body=None, params=None, raw=False, move_id=None):
        assert_allowed(path)
        headers = {MOVE_ID_HEADER: move_id} if move_id else {}
        r = None
        for attempt in range(self.retries + 1):
            await self.limiter.wait()
            try:
                r = await self.http.request(method, path, json=body, params=params, headers=headers)
            except httpx.TransportError as e:
                if attempt == self.retries:
                    if method == "POST":
                        raise UncertainOutcome(move_id or "", e) from e
                    raise
                await asyncio.sleep(0.5 * 2**attempt)
                continue
            wait = r.headers.get("Retry-After", "")
            short = wait.isdigit() and int(wait) <= MAX_RETRY_AFTER_S
            if r.status_code not in RETRY_STATUS or attempt == self.retries or (r.status_code == 429 and not short):
                break
            await asyncio.sleep(float(wait) if wait.isdigit() else 0.5 * 2**attempt)
        if (left := r.headers.get(REMAINING_HEADER, "")).isdigit():
            self.practice_remaining = int(left)
        if r.status_code >= 400:
            try:
                detail = r.json().get("detail", r.text)
            except (ValueError, AttributeError):
                detail = r.text
            raise ArenaError(r.status_code, detail)
        return r.content if raw else r.json()

    async def me(self) -> dict:
        return await self._call("GET", "/me")

    async def cases(self, set_: str) -> list[dict]:
        self._wire_agent_clock()  # coordinator start: before any decision, with or without a cap
        if getattr(self.agent, "trades", None):
            meta = self.case_meta
            if meta is None:
                set_ = "sandbox" if self.case_id.startswith("case:D") else "practice"
                meta = next((c for c in await self.arena.cases(set_) if c["case_id"] == self.case_id), None)
            if meta:
                await asyncio.to_thread(self.agent.trades.prepare, meta)
        if (done := self.journal.finished(self.case_id)) is not None:
            return done
        session_id = self.journal.session_for(self.case_id)
        if session_id is None:
            pend = [p for p in self.journal.pending(case_id=self.case_id) if p["kind"] == "open"]
            payload = {"case_id": self.case_id}
            intent = pend[-1] if pend else self.journal.intent(self.case_id, None, None, "open", payload)
            try:
                r = await self.arena.open_session(self.case_id, intent["move_id"])
            except ArenaError as e:
                running = RUNNING.search(str(e.detail)) if e.status == 409 else None
                if not running:
                    self.journal.outcome(intent["move_id"], "failed", http=e.status, detail=str(e.detail))
                    raise
                self.journal.outcome(intent["move_id"], "abandoned", resumed=running.group(1))
                session_id = running.group(1)
            else:
                self.journal.outcome(intent["move_id"], "done", session=r["session_id"])
                self.journal.session(self.case_id, r["session_id"], r["case"])
                now = self.clock.time()
                self.st = CaseState(case=r["case"], session_id=r["session_id"], opened_at=now)
                for sid, events in r["threads"].items():
                    self.st.threads[sid] = ThreadState(sid, list(events), deadline_utc=now + self.move_limit_s)
                for t in self.st.threads.values():
                    for m in t.events:
                        await self._docs(m)
                self._trace("open", suppliers=list(self.st.threads))
                return None
            self.journal.session(self.case_id, session_id, self.case_meta)
        return await self._resume(session_id)
    started, closed, caps = {}, set(), {}
    failures = 0

    def one(case, deadline):
        try:
            return play_case(RemoteTable(client, case), case["case_id"], new_agent(), deadline)
        except Exception as e:
            log.exception("%s failed", case["case_id"])
            return e

    from .prewarm import prewarm

    prewarm(agent=new_agent())  # package, dossiers, facts: before the first poll
    with ThreadPoolExecutor(max_workers=parallel) as pool:
        while len(closed) < waves or not all(f.done() for f in started.values()):
            try:
                try:
                    cases = client.cases("final")
                except ArenaError as e:
                    if e.status != 403:
                        raise
                    cases = []
                for case in cases:
                    if not case.get("open"):
                        closed.add(case["wave"])
                        continue
                    if case.get("seconds_left") is not None:
                        caps[case["wave"]] = time.time() + case["seconds_left"]
                    if case["case_id"] not in started and case.get("seconds_left"):
                        if case["wave"] not in {c["wave"] for c in cases if c["case_id"] in started}:
                            log.warning("wave %s started: %s", case["wave"], case.get("theme"))
                        started[case["case_id"]] = pool.submit(
                            one, case, functools.partial(caps.get, case["wave"]))
            except Exception as e:  # never let the final die: live sessions and later waves continue
                failures += 1
                pause = poll_backoff(poll, failures, rng)
                log.warning("final case list failed (%d in a row): %r; retry in %.1fs", failures, e, pause)
                sleep(pause)
                continue
            failures = 0
            sleep(poll)
